const current = $input.first().json;
const context = current.context || {};
const payload = current.payload || {};
const planCandidate = payload.plan || current.plan || {};
const lineDecisions =
  payload.line_decisions ||
  payload.plan?.line_decisions ||
  current.line_decisions ||
  current.plan?.line_decisions ||
  [];

function affectedLinesFromOperations(operations) {
  const seen = new Set();
  for (const operation of operations || []) {
    const path = operation.path || '';
    const parts = path.split('/').filter(Boolean);
    const lineIndex = parts.indexOf('lines');
    if (lineIndex >= 0 && parts[lineIndex + 1]) {
      seen.add(parts[lineIndex + 1]);
    }
  }
  return Array.from(seen).sort();
}

const candidatePatch =
  payload.candidate_patch ||
  payload.candidate_patch_summary ||
  current.candidate_patch ||
  current.body?.candidate_patch ||
  {};
const affectedLines =
  context.affected_lines ||
  payload.affected_lines ||
  current.affected_lines ||
  candidatePatch.affected_lines ||
  affectedLinesFromOperations(candidatePatch.operations);

const normalizedPlan = {
  ...planCandidate,
  line_decisions: lineDecisions
};

const normalizedContext = {
  ...context,
  trt_id: context.trt_id || normalizedPlan.trt_id || null,
  trt_version: context.trt_version || normalizedPlan.trt_version || null,
  reconciliation_plan_id: context.reconciliation_plan_id || normalizedPlan.plan_id || null,
  affected_lines: affectedLines
};

const onlyNoChange = lineDecisions.length > 0 && lineDecisions.every(item => item.decision === 'NO_CHANGE');
const allowBaseline = current.allow_baseline_on_no_change === true || current.body?.allow_baseline_on_no_change === true || context.allow_baseline_on_no_change === true;
const evaluatesReleasedPatchImpact = affectedLines.length > 0;

if (onlyNoChange && !allowBaseline && !evaluatesReleasedPatchImpact) {
  return [{
    json: {
      status: 'NO_EFFECT',
      reason: 'Reconciliation plan contains no changed lines.',
      context: normalizedContext,
      payload: { ...payload, plan: normalizedPlan },
      errors: []
    }
  }];
}

return [{
  json: {
    status: 'READY_FOR_SCENARIO_GENERATION',
    context: normalizedContext,
    payload: { ...payload, plan: normalizedPlan },
    errors: []
  }
}];

const input = $input.first().json;
const context = input.context || {};
const plan = input.payload?.plan || {};
const missing = [];

for (const field of ['release_id', 'trt_id', 'trt_version', 'reconciliation_plan_id']) {
  if (!context[field]) missing.push(field);
}

if (missing.length) {
  const message = `Missing ScenarioSpec generation fields: ${missing.join(', ')}`;
  return [{
    json: {
      status: 'REJECTED',
      context,
      ids: {
        release_id: context.release_id || null,
        audit_id: context.audit_id || null,
        trt_id: context.trt_id || null,
        trt_version: context.trt_version || null,
        reconciliation_plan_id: context.reconciliation_plan_id || null,
        scenario_spec_id: null
      },
      payload: {
        ...(input.payload || {}),
        plan,
        message,
        missing_fields: missing
      },
      errors: [message]
    }
  }];
}

return [{
  json: {
    ...input,
    status: 'READY_FOR_SCENARIO_GENERATION',
    context,
    payload: {
      ...(input.payload || {}),
      plan
    },
    scenario_request: {
      release_id: context.release_id,
      trt_id: context.trt_id,
      trt_version: context.trt_version,
      reconciliation_plan_id: context.reconciliation_plan_id,
      candidate_strategy_id: 'primary',
      scenario_template_id: 'surgical_sorting_v1',
      include_waiting_scenarios: false,
      affected_lines: context.affected_lines || []
    },
    errors: []
  }
}];

const input = $input.first().json;
const message = (input.errors || [])[0] || 'Missing ScenarioSpec generation fields.';
return [{
  json: {
    status: 'REJECTED',
    context: input.context || {},
    ids: input.ids || {
      release_id: input.context?.release_id || null,
      audit_id: input.context?.audit_id || null,
      trt_id: input.context?.trt_id || null,
      trt_version: input.context?.trt_version || null,
      reconciliation_plan_id: input.context?.reconciliation_plan_id || null,
      scenario_spec_id: null
    },
    payload: input.payload || { message },
    errors: [message]
  }
}];
